 record={'criterion':criterion,'result':status,'command':cmd,'source_sha':source,'artifact_sha256':artifact,'environment':'Cloud Python3.12/JDK17/Android SDK36/NDK28.2; no attached handset','dataset_identity':'Explicitly synthetic host fixtures only; physical datasets unavailable','evidence':'/workspace/campaign/evidence/'+role+'/gradle.log','detail':detail}
 for i,(key,value) in enumerate(record.items()):lines.append(('  - ' if i==0 else '    ')+key+': '+json.dumps(value))
